// _PORT_MESSAGE: 0x18 (24) bytes, packed to 4
#pragma pack(push, 4)
struct _PORT_MESSAGE
{
    union
    {
        struct
        {
            CSHORT DataLength;
            CSHORT TotalLength;
        } s1;
        ULONG Length;
    } u1;
    union
    {
        struct
        {
            CSHORT Type;
            CSHORT DataInfoOffset;
        } s2;
        ULONG ZeroInit;
    } u2;
    union
    {
        CLIENT_ID ClientId;
        DOUBLE DoNotUseThisField;
    };
    ULONG MessageId;
    union
    {
        SIZE_T ClientViewSize;
        ULONG CallbackId;
    };
};
#pragma pack(pop)

typedef struct _PORT_MESSAGE PORT_MESSAGE;

typedef struct _PORT_MESSAGE *PPORT_MESSAGE;

// _PORT_VIEW: 0x18 (24) bytes, packed to 4
#pragma pack(push, 4)
struct _PORT_VIEW
{
    ULONG Length;
    HANDLE SectionHandle;
    ULONG SectionOffset;
    SIZE_T ViewSize;
    PVOID ViewBase;
    PVOID ViewRemoteBase;
};
#pragma pack(pop)

typedef struct _PORT_VIEW PORT_VIEW;

typedef struct _PORT_VIEW *PPORT_VIEW;

// _REMOTE_PORT_VIEW: 0xC (12) bytes, packed to 4
#pragma pack(push, 4)
struct _REMOTE_PORT_VIEW
{
    ULONG Length;
    SIZE_T ViewSize;
    PVOID ViewBase;
};
#pragma pack(pop)

typedef struct _REMOTE_PORT_VIEW REMOTE_PORT_VIEW;

typedef struct _REMOTE_PORT_VIEW *PREMOTE_PORT_VIEW;

// _VAD_HEADER: 0x30 (48) bytes, packed to 4
#pragma pack(push, 4)
struct _VAD_HEADER
{
    PVOID StartVPN;
    PVOID EndVPN;
    struct _VAD_HEADER *ParentLink;
    struct _VAD_HEADER *LeftLink;
    struct _VAD_HEADER *RightLink;
    ULONG Flags;
    PVOID ControlArea;
    PVOID FirstProtoPte;
    PVOID LastPTE;
    ULONG Unknown;
    LIST_ENTRY Secured;
};
#pragma pack(pop)

typedef struct _VAD_HEADER VAD_HEADER;

typedef struct _VAD_HEADER *PVAD_HEADER;


